from pathlib import Path
import re

p = Path('appsrc/public/index.html')
s = p.read_text(encoding='utf-8')

DATA = ""

# Remove the previous Gran Tarajal hero override if present.
s = re.sub(r'\s*<style id="fvm-gran-tarajal-east-hero">.*?</style>\s*', '\n', s, flags=re.S)

css = f'''\n<style id="fvm-gran-tarajal-east-hero">\n/* FVM_EXACT_BANNER_20260912 */\n.v5hero{{background-image:url("data:image/webp;base64,{DATA}")!important;background-repeat:no-repeat!important;background-position:center center!important;background-size:100% 100%!important;aspect-ratio:1916/420!important;min-height:0!important;height:auto!important;width:100%!important}}\n.v5hero>.heroInner,.v5hero>.heroTradeCollage{{display:none!important}}\n@media(max-width:700px){{.v5hero{{aspect-ratio:auto!important;height:245px!important;min-height:245px!important;background-size:auto 100%!important;background-position:left center!important}}}}\n</style>\n'''

s = s.replace('</head>', css + '</head>', 1)
p.write_text(s, encoding='utf-8')
